export const UK_GAME_BIBLE_CHAPTERS: GameBibleChapter[] = EN_GAME_BIBLE_CHAPTERS.map((source) => {
  const localized = ukCopy[source.id];
  if (!localized) throw new Error(`Missing Ukrainian Game Design Bible chapter: ${source.id}`);
  return defineGameBibleChapter({
    id: source.id,
    group: localized.group,
    title: localized.title,
    summary: localized.summary,
    keywords: localized.keywords,
    topicIdsBySection: source.sections.map((section) => section.topicIds) as [string[], string[], string[], string[], string[]],
    sourceRefs: source.sections[0]?.sourceRefs ?? [],
    decisionRefs: source.sections[0]?.decisionRefs ?? [],
    relatedChapterIds: source.relatedChapterIds,
    copy: localized.copy,
  });
});
